 public static string NombreFisico(string nombre)=>Tablas.TryGetValue(nombre.Replace("compat.","l1.",StringComparison.Ordinal),out var t)?t.Nombre:nombre;
 public static async Task<DataTable> Convertir(SqlConnection conexion,SqlTransaction? transaccion,string nombre,DataTable origen){
  if(!Tablas.TryGetValue(nombre.Replace("compat.","l1.",StringComparison.Ordinal),out var tabla))return origen;
  var destino=new DataTable();var campos=tabla.Campos.Where(f=>origen.Columns.Contains(f.Origen)).ToArray();
  foreach(var campo in campos)destino.Columns.Add(campo.Destino,NormalizedJournal.DataType(campo.Tipo));
  var posiciones=(await conexion.QueryAsync("SELECT codigo_posicion_origen Codigo,id_posicion Id FROM l1.POSICION",transaction:transaccion)).ToDictionary(x=>(string)x.Codigo,x=>(int)x.Id);
  var puestos=(await conexion.QueryAsync("SELECT codigo_puesto Codigo,id_puesto Id FROM l1.PUESTO_LOGISTICO",transaction:transaccion)).ToDictionary(x=>(string)x.Codigo,x=>(int)x.Id);
  var turnos=(await conexion.QueryAsync("SELECT codigo_turno Codigo,id_turno Id FROM l1.TURNO",transaction:transaccion)).ToDictionary(x=>(string)x.Codigo,x=>(int)x.Id);
  foreach(DataRow fila in origen.Rows){var nueva=destino.NewRow();foreach(var campo in campos){object valor=fila[campo.Origen];if(valor is not DBNull){valor=campo.Conversion switch{"position"=>posiciones[(string)valor],"post"=>puestos[(string)valor],"turn"=>turnos[(string)valor],"micro"=>DateTime.UnixEpoch.AddTicks(checked(Convert.ToInt64(valor)*10)),_=>campo.Tipo=="int"?checked(Convert.ToInt32(valor)):valor};}nueva[campo.Destino]=valor;}destino.Rows.Add(nueva);}
  return destino;
 }
